<script setup>
import { ref, watch, onUnmounted } from 'vue'
import { useRoute } from 'vue-router'
import { api, state, isLive, isUpcoming, statusLabel, day, time } from '../state'
import Badge from '../components/Badge.vue'
import Icon from '../components/Icon.vue'
import DataFreshness from '../components/DataFreshness.vue'
import MatchPreview from '../components/MatchPreview.vue'
const route = useRoute(), detail = ref(null), loading = ref(false), error = ref(''), tab = ref('events')
let version = 0
async function loadDetail({ manual = false } = {}) {
  const requestVersion = ++version
  loading.value = !detail.value; error.value = ''
  try { const data = await api(`/api/matches/${route.params.id}`, { manual }); if (requestVersion === version) detail.value = data }
  catch (e) { if (requestVersion === version) error.value = e.message }
  finally { if (requestVersion === version) loading.value = false }
}
watch(() => route.params.id, () => { detail.value = null; tab.value = 'events'; loadDetail() }, { immediate: true })
watch(() => state.refreshSerial, () => loadDetail({ manual: state.lastRefreshWasManual }))
onUnmounted(() => { version++ })
function percent(value, other) { const a = parseFloat(value) || 0, b = parseFloat(other) || 0; return a + b ? a / (a + b) * 100 : 50 }
function eventLabel(e) { if (e.type === 'Goal') return e.detail === 'Own Goal' ? 'But contre son camp' : e.detail === 'Missed Penalty' ? 'Penalty manqué' : 'But'; if (e.type === 'Card') return e.detail === 'Red Card' ? 'Carton rouge' : 'Carton jaune'; if (e.type === 'subst') return 'Remplacement'; return e.detail || e.type }
</script>
<template><RouterLink to="/" class="back-link"><Icon name="back" :size="16" />Toutes les rencontres</RouterLink><div v-if="loading" class="loading-state" role="status"><span class="loader"></span><h2>Chargement du match…</h2></div><div v-else-if="error" class="alert error" role="alert"><p>{{ error }}</p><button class="button" @click="loadDetail({ manual: true })" :disabled="state.refreshMode === 'pause'">Réessayer</button></div><template v-else-if="detail"><DataFreshness v-if="state.mode === 'api'" :fetched-at="detail.fetchedAt" :stale="detail.stale" label="Détails du match" /><section class="match-scoreboard"><div class="scoreboard-meta"><span>LIGUE 1 <b>·</b> JOURNÉE {{ detail.fixture.round || '—' }}</span><span>{{ day(detail.fixture.date, { weekday: 'long', year: 'numeric' }) }} · {{ time(detail.fixture.date) }}</span></div><div class="scoreboard-teams"><RouterLink :to="`/equipes/${detail.fixture.home.id}`"><Badge :team="detail.fixture.home" size="hero-badge" /><h1>{{ detail.fixture.home.name }}</h1></RouterLink><div class="big-score"><span class="match-status" :class="{ live: isLive(detail.fixture) }"><span v-if="isLive(detail.fixture)" class="live-dot"></span>{{ statusLabel(detail.fixture) }}</span><strong>{{ detail.fixture.homeGoals ?? '–' }}<span>:</span>{{ detail.fixture.awayGoals ?? '–' }}</strong><span class="small-text">{{ state.mode === 'demo' ? 'SCÉNARIO FICTIF' : isLive(detail.fixture) ? 'MATCH EN COURS' : '' }}</span></div><RouterLink :to="`/equipes/${detail.fixture.away.id}`"><Badge :team="detail.fixture.away" size="hero-badge" /><h1>{{ detail.fixture.away.name }}</h1></RouterLink></div><p class="scoreboard-venue"><Icon name="pin" :size="15" />{{ detail.fixture.venue || 'Stade non renseigné' }}</p></section><MatchPreview v-if="['NS','TBD','PST'].includes(detail.fixture.status)" :fixture="detail.fixture" /><section class="panel match-detail"><div class="detail-tabs" role="group" aria-label="Informations du match"><button :class="{ active: tab === 'events' }" :aria-pressed="tab === 'events'" @click="tab = 'events'">Fil du match</button><button :class="{ active: tab === 'stats' }" :aria-pressed="tab === 'stats'" @click="tab = 'stats'">Statistiques</button></div><div v-if="tab === 'events'" class="event-list"><div v-for="(event, index) in detail.events" :key="index" class="event"><span class="event-minute">{{ event.minute ?? '—' }}{{ event.extra ? `+${event.extra}` : '' }}′</span><span class="event-symbol" :class="{ card: event.type === 'Card', red: event.detail === 'Red Card' }"><Icon v-if="event.type === 'Goal'" name="ball" :size="19" /><span v-else-if="event.type === 'Card'" class="card-shape"></span><Icon v-else name="refresh" :size="17" /></span><div><strong>{{ event.player }}</strong><p>{{ eventLabel(event) }} · {{ event.teamId === detail.fixture.home.id ? detail.fixture.home.name : detail.fixture.away.name }}</p></div></div><div v-if="!detail.events.length" class="empty"><Icon name="clock" :size="32" /><h3>{{ isUpcoming(detail.fixture) ? 'Le match n’a pas encore commencé' : 'Aucun événement disponible' }}</h3><p>{{ isUpcoming(detail.fixture) ? 'Les événements apparaîtront ici lorsqu’ils seront transmis par le fournisseur.' : 'Les événements ne sont pas encore transmis ou ne sont pas inclus dans les données disponibles.' }}</p></div></div><div v-else class="statistics"><div v-for="stat in detail.stats" :key="stat.label" class="stat-row"><div><b>{{ stat.home ?? '—' }}</b><span>{{ stat.label }}</span><b>{{ stat.away ?? '—' }}</b></div><div class="stat-track"><span :style="{ width: `${percent(stat.home, stat.away)}%` }"></span></div></div><div v-if="!detail.stats.length" class="empty"><Icon name="table" :size="32" /><h3>Statistiques indisponibles</h3><p>{{ isUpcoming(detail.fixture) ? 'Elles seront affichées après le début du match si le fournisseur les transmet.' : 'Le fournisseur ne transmet pas ces statistiques pour ce match ou cette offre.' }}</p></div></div></section><p class="update-note"><Icon name="info" :size="14" />{{ state.mode === 'demo' ? 'Les scores, événements, noms de joueurs et statistiques de ce match sont fictifs.' : `Dernière mise à jour : ${day(detail.fetchedAt)} à ${time(detail.fetchedAt)}. Les détails sont conservés en cache 15 minutes pour économiser le quota.` }}<button v-if="state.mode === 'api'" class="text-button" @click="loadDetail({ manual: true })" :disabled="state.refreshMode === 'pause'">Actualiser</button></p></template></template>
